"""Local reproducible refinement, starting from design.json (audit helper)."""
import json,numpy as np
from gri_bench.api import *
i=load_instance(); e=Experiment(i); keys=PARAMETERS
b=np.array([i['bounds'][k] for k in keys]); log=np.array([1,0,1,1,1,0],bool)
def enc(p):
 p=np.array([p[k] for k in keys]); return np.where(log,(np.log(np.maximum(p,1e-12))-np.log(np.maximum(b[:,0],1e-12)))/(np.log(b[:,1])-np.log(np.maximum(b[:,0],1e-12))),(p-b[:,0])/(b[:,1]-b[:,0]))
def dec(u):
 u=np.clip(u,0,1); p=np.where(log,np.exp(np.log(np.maximum(b[:,0],1e-12))+u*(np.log(b[:,1])-np.log(np.maximum(b[:,0],1e-12)))),b[:,0]+u*(b[:,1]-b[:,0])); p=np.clip(p,b[:,0],b[:,1]); return dict(zip(keys,p))
def score(m): return m['mean_tir']-400*(max(0,m['max_trajectory_tbr70']-2.8)+max(0,m['max_trajectory_tbr54']-.4)+max(0,55-m['minimum_glucose'])/10)
d=json.load(open('/work/output/design.json')); u0=enc(d['parameters']); best=(-1e9,u0,None); rng=np.random.default_rng(7719); hist=[]
for k in range(130):
 if k==0:u=u0
 elif k<50:u=np.clip(u0+rng.normal(0,[.10,.10,.13,.13,.16,0]),0,1)
 else:
  elite=sorted(hist,key=lambda z:z[0],reverse=True)[:10][rng.integers(10)][1]
  u=np.clip(elite+rng.normal(0,[.055,.04,.07,.07,.08,0]),0,1)
 m=e.evaluate({'mode':'responsive','parameters':dec(u)}); s=score(m); hist.append((s,u))
 if s>best[0]:
  best=(s,u,m);save_design({'mode':'responsive','parameters':dec(u)});print('BEST',k,s,dec(u),{q:m[q] for q in ['mean_tir','max_trajectory_tbr70','max_trajectory_tbr54','minimum_glucose']},flush=True)
print(json.dumps(best[2],indent=2))
